function drawOrder(){const show=snapshot.state.kind==='order'&&snapshot.state.stage==='tournament_round'&&!snapshot.own.done;$('orderTiles').hidden=$('orderSelection').hidden=$('resetOrder').hidden=$('undoOrder').hidden=!show;$('answer').hidden=['odd','grid','angle','gradient','order','path','reach','arrows','chess','area','population','hotcold','route','memory','duck','mirror','audio','laser','map','nearcity','clock'].includes(snapshot.state.kind);document.querySelector('label[for="answer"]').hidden=['odd','grid','angle','gradient','order','path','reach','arrows','chess','area','population','hotcold','route','memory','duck','mirror','audio','laser','map','nearcity','clock'].includes(snapshot.state.kind);$('orderTiles').replaceChildren(...(show?snapshot.state.tiles:[]).map((n,i)=>{const b=document.createElement('button');b.type='button';b.textContent=n;b.dataset.index=String(i+1);b.style.cssText='width:100%;padding:13px 4px;background:#30445e;color:white';const step=$('answer').value.indexOf(String(i+1))+1;b.setAttribute('aria-pressed',step?'true':'false');b.setAttribute('aria-label','الرقم '+n+(step?'، الاختيار '+step:'، غير مختار'));b.onclick=e=>{if(busy||!roundEditable()||readPending()||$('answer').value.includes(String(i+1)))return;$('answer').value+=String(i+1);HubStorage.setItem(draftKey(),$('answer').value);drawOrder();drawPath();applyBusy();if(e.detail===0){const next=[...$('orderTiles').children].find(b=>!b.disabled);(next||$('submitAnswer')).focus()}};return b}));$('orderSelection').textContent='ترتيبك: '+[...$('answer').value].map(i=>snapshot.state.tiles?.[Number(i)-1]).join(' ← ')}
$('resetOrder').onclick=()=>{if(busy||!roundEditable()||readPending())return;$('answer').value='';HubStorage.removeItem(draftKey());drawOrder();applyBusy()};

function pathAllowed(cell){const v=$('answer').value;if(v.includes(cell))return false;if(!v)return cell===snapshot.state.path_start;const a=v.charCodeAt(v.length-1)-65,b=cell.charCodeAt(0)-65;return Math.abs(Math.floor(a/4)-Math.floor(b/4))+Math.abs(a%4-b%4)===1}
function drawPath(){const s=snapshot.state,show=s.kind==='path'&&s.stage==='tournament_round'&&!snapshot.own.done,reveal=s.kind==='path'&&s.stage==='tournament_reveal';$('pathTiles').hidden=!(show||reveal);$('pathProgress').hidden=$('resetPath').hidden=$('undoPath').hidden=!show;const v=reveal?s.answer:$('answer').value;$('pathTiles').replaceChildren(...(show||reveal?Array.from({length:16},(_,i)=>String.fromCharCode(65+i)):[]).map(cell=>{const b=document.createElement('button'),step=v.indexOf(cell)+1,mark=cell===s.path_start?'بداية':cell===s.path_end?'نهاية':cell===s.path_checkpoint?'★':'';b.type='button';b.dataset.cell=cell;b.textContent=step?String(step):mark||'·';b.setAttribute('aria-pressed',step?'true':'false');const pos=cell.charCodeAt(0)-65;b.setAttribute('aria-label','صف '+(Math.floor(pos/4)+1)+'، عمود '+(pos%4+1)+' من اليسار'+(cell===s.path_checkpoint?'، النجمة، يجب أن تكون الخطوة 8':mark?'، '+mark:'')+(step?'، الخطوة '+step:'، غير مختار'));b.style.cssText='width:100%;min-height:52px;margin:0;padding:8px 2px;font-size:.9rem;background:'+(step?'#446354':'#253c57')+';color:white';b.disabled=!show||busy||!!readPending()||!pathAllowed(cell);b.onclick=e=>{if(busy||!roundEditable()||readPending()||!pathAllowed(cell))return;$('answer').value+=cell;HubStorage.setItem(draftKey(),$('answer').value);drawPath();applyBusy();if(e.detail===0){const next=[...$('pathTiles').children].find(b=>!b.disabled);(next||$('submitAnswer')).focus()}};return b}));$('pathProgress').textContent='خطواتك: '+$('answer').value.length+' من 16. النجمة يجب أن تكون الخطوة 8.'}
$('resetPath').onclick=()=>{if(busy||!roundEditable()||readPending())return;$('answer').value='';HubStorage.removeItem(draftKey());drawPath();applyBusy()};

function validPathPrefix(v,start){return /^[A-P]{0,16}$/.test(v)&&new Set(v).size===v.length&&(!v||v[0]===start)&&[...v].every((c,i)=>!i||Math.abs(Math.floor((c.charCodeAt(0)-65)/4)-Math.floor((v.charCodeAt(i-1)-65)/4))+Math.abs((c.charCodeAt(0)-65)%4-(v.charCodeAt(i-1)-65)%4)===1)}

function ownStatusText(state,own){if(state.kind==='nearcity')return own.done?'ثُبّت دبوسك، لا تعديل بعد التثبيت.':'دبوس واحد نهائي، المسودة لا تُحسب.';const active=state.stage==='tournament_round',retry=state.kind==='acting'?'ليست هذه الفكرة، جرّب اسماً آخر.':state.kind==='trivia'?'ليست هذه الإجابة. جرّب مرة أخرى.':state.kind==='map'?'الدبوس خارج الدولة المطلوبة. جرّب موضعاً آخر.':state.kind==='laser'?'لم يصل الشعاع إلى الهدف. غيّر المرايا.':state.kind==='memory'?'الترتيب غير صحيح. جرّب المسار من جديد.':state.kind==='route'?'وصلت بطريق أطول من الأقصر. جرّب طريقاً أقصر.':state.kind==='hotcold'?'ليست هي، اتبع تلميح المسافة والاتجاه.':['flag','shape'].includes(state.kind)?'ليست هذه الدولة. جرّب اسماً آخر.':state.kind==='path'?'المسار غير صحيح. جرّب مساراً آخر.':state.kind==='order'?'الترتيب غير صحيح. جرّب مرة أخرى.':state.kind==='chess'?'نقلة قانونية، لكنها ليست مات. جرّب نقلة أخرى.':state.kind==='arrows'?'ترتيب الخروج غير صحيح. جرّب ترتيباً آخر.':state.kind==='reach'?'لم تصل للهدف. جرّب تركيباً آخر.':'ليس هذا الرقم. جرّب مرة أخرى.',hint={try_again:retry,higher:'الرقم أعلى ↑',lower:'الرقم أقل ↓',pinned:'ثبّت دبوسك، النتائج بعد نهاية الوقت.',estimated:'ثبّت تقديرك، النتائج بعد نهاية الوقت.',correct:state.kind==='acting'?'نجح الفريق! ينتظر الجميع نهاية الجولة.':state.kind==='clock'?'ثبّتت نتيجة توقيتك. انتظر نهاية الجولة.':'حل صحيح! انتظر نهاية الوقت للنتيجة.',wrong:'انتهت محاولاتك. انتظر نهاية الوقت.'};return 'محاولاتك: '+own.attempts+' | أخطاؤك: '+own.mistakes+(active?' | المتبقي: '+(own.done?0:Math.max(0,state.max_attempts-own.attempts)):'')+(own.hint?' · '+(!active?(own.hint==='estimated'?'ثبّت تقديراً.':own.hint==='correct'?'حل صحيح.':'انتهت الجولة.'):hint[own.hint]||''):'')}

function forgetIdentityMessage(room){const unfinished=room&&room.state.stage!=='tournament_finished',host=room&&room.me===room.host_id;return(host&&unfinished?'أنت المضيف. نسيان دخولك بدون تسليم الإدارة قد يترك أصحابك بانتظارك. سلّم الإدارة أولاً إن أردت استمرار البطولة. ':'')+'الكود لا يستعيد هويتك أو نقاطك السابقة. تنسى هذا الدخول؟'}
function drawHostGuidance(room){const host=room.me===room.host_id,name=room.players.find(p=>p.id===room.host_id)?.name||'المضيف',stage=room.state.stage,finished=stage==='tournament_finished';$('hostRole').textContent=finished?'انتهت البطولة، والنتائج محفوظة في الغرفة.':host?'أنت المضيف. تفتح الجولات وتستطيع تسليم الإدارة للاعب آخر.':'المضيف: '+name+'، هو من يفتح الجولات.';const wait=!host&&stage==='tournament_reveal';$('hostWait').hidden=!wait;$('hostWait').textContent=wait?'انتهى وقت الجولة. بانتظار '+name+(room.state.number>=room.state.total?' لإظهار النتيجة النهائية. ':' لفتح الجولة التالية. ')+'إذا غاب، تنتظرون رجوعه أو تسليمه الإدارة. لا انتقال تلقائي للإدارة.':''}

$('discardPending').onclick=()=>{if(busy||!roundEditable()||snapshot?.state.stage!=='tournament_round'||snapshot.own.done||!readPending()?.corrupt)return;if(!confirm('تعذّر قراءة الطلب، وقد يكون الخادم حسب المحاولة السابقة. حدّث الغرفة أولاً. نسيان هذا الطلب لا يلغي ما وصل للخادم، والمحاولة التالية قد تُحسب محاولة أخرى. تنسى الطلب التالف؟'))return;HubStorage.removeItem(pendingKey());applyBusy()};

function gameHelp(kind){return {odd:'اختر المربع المختلف في الإضاءة ثم ثبّت. محاولة واحدة و60 ثانية. 10000 للصحيح، صفر للخطأ، بلا مكافأة سرعة.',grid:'القيم تتقدم بخطوة ثابتة عبر الصفوف من أعلى اليسار، وتعود للبداية بعد9. اختر قيمة الخانة الناقصة. محاولة واحدة و60 ثانية، 10000 للصحيح دون سرعة.',angle:'طابق الخط الأصفر مع الزاوية الزرقاء. ثبّت مرة واحدة خلال60ثانية. فرق5درجات أو أقل يمنح10000، وإلا صفر. ليست قياساً مادياً.',gradient:'رتّب الألوان من الداكن إلى الفاتح من أعلى اليسار. اضغط مربعين للتبديل، ثم ثبّت الترتيب مرة واحدة خلال60ثانية. 10000للصحيح، دون سرعة. الأرقام مواقع وليست الحل.',mirror:'جهّز الشاشة، المرايا تظهر5ثوانٍ ثم تختفي. الشعاع يدخل من المنفذ الأصفر، اختر منفذ خروجه بعد الانعكاسات وثبّت مرة واحدة. المرآة المائلة تعكس الشعاع90درجة. 10000للصحيح وصفرللخطأ، بلا سرعة. إن انقطعت مراحل أحدكم تلغى الجولة للجميع دون نقاط، والحل بعد120ثانية. المنافذ1-20تدور مع عقارب الساعة من أعلى اليسار.',duck:'جهّز الشاشة ثم اعرض الأسهم لخمس ثوانٍ. بعد اختفائها، ابدأ من البطّة واتبع 6 أسهم خطوة بخطوة دون التفاف خارج الشبكة، ثم اختر مربع النهاية وثبّت. 10000 للصحيح وصفر للخطأ، بلا مكافأة سرعة. الخروج أو انقطاع مراحل أحدكم يلغي الجولة للجميع دون نقاط. الإلغاء لا يكشف الحل قبل نهاية120ثانية.',nearcity:'دبوس واحد نهائي خلال 60 ثانية، قرب مركز المدينة التقريبي في Natural Earth. الأصفر يظهر بعد النهاية. الترتيب حسب المسافة الجوية المقربة لأقرب كيلومتر، المتساوون يتعادلون. 10000 للأقرب، ثم 9000 للمسافة التالية المختلفة وهكذا. لا مكافأة سرعة، والنقاط نسبية حتى لو ثبت لاعب واحد فقط. التكبير والتحريك والمسودة مجانية. ليست نقطة مبنى أو مركزاً رسمياً دقيقاً.',closest:'تقدير واحد نهائي خلال 60 ثانية. الأقرب إلى الرقم الصحيح يأخذ 10000، ثم 9000 للخطأ التالي المختلف وهكذا. المسافات المتساوية تتعادل، ولا أفضلية للسرعة. النقاط نسبية بين المشاركين، حتى لو كان تخمين واحد فقط. اكتب الوحدة المطلوبة دون فواصل آلاف، وحتى 3 منازل عشرية.',acting:'ممثّل يرى الفكرة وحده، والبقية يخمّنون خلال 60 ثانية. نجاح أحدكم يعطي الجميع النقاط نفسها دون تغيير ترتيبكم.',clock:'ابدأ العداد ثم أوقفه عند الزمن المطلوب. تختفي الأرقام بعد أول ثانية. التدريب وإعادة المحاولة قبل التثبيت مسموحان؛ أول نتيجة مثبتة فقط تُحسب. النقاط تقلّ مع مقدار الخطأ عن الهدف، ولا مكافأة لبدء المحاولة مبكراً. لديك 60 ثانية للجولة.',trivia:'اكتب الإجابة بالعربية أو الإنجليزية. عينة أصلية من 45 سؤالاً في 9 فئات، مع مصدر لكل إجابة. نقبل أسماء محددة وتطبيع الحروف والأرقام، وليس كل خطأ إملائي. 3 محاولات و60 ثانية؛ المصدر يظهر بعد الجولة. ',map:'ضع دبوساً داخل الدولة المطلوبة ثم ثبّت المحاولة. أي نقطة داخل حدود بيانات Natural Earth المحددة تُقبل، مع احتساب الجزر واستبعاد الثقوب. ليس المطلوب العاصمة أو المركز. 3 محاولات و60 ثانية. الدبوس والتحريك والتكبير مسودة مجانية؛ لن تُحسب حتى التثبيت. قد تختلف الحدود المبسّطة أو المتنازع عليها عن مصادر أخرى.',laser:'دوّر المرايا بين / و\\ حتى يخرج الشعاع عند ◎. يتحرك أفقيّاً أو عموديّاً وينعكس على المرايا. لا نعرض نتيجة التجربة قبل تثبيت محاولة كاملة؛ التدوير والتراجع والمسح مسودة مجانية. لديك 3 محاولات و60 ثانية. ● مدخل الشعاع. الحل يكشف بعد انتهاء الوقت.',memory:'تجربة مخفية: معاينة ظاهرة 5 ثوانٍ ثم استرجاع حتى 55 ثانية. لا مكافأة سرعة. الانقطاع أو عدم إكمال مراحل أي لاعب يلغي الجولة للجميع، ولا تتغير النقاط حتى التأكيد النهائي. لا تخفِ الصفحة أثناء دورك',route:'صِل من دولة البداية إلى النهاية بأقصر طريق عبر دول متجاورة داخل قائمة 15 دولة أوروبية فقط. اختر الجار، ويمكنك التراجع أو المسح قبل التثبيت دون محاولة. 3 محاولات كاملة و60 ثانية. هذا لغز جغرافي ثابت وليس نصيحة سفر أو تأكيداً لفتح الحدود.',hotcold:'اختر دولة من عينة 18 دولة. بعد كل تخمين نعرض تلميحك الخاص: المسافة التقريبية والاتجاه إلى الدولة الخفية، وهل اقتربت من التخمين السابق. المسافات بين نقاط داخلية ثابتة، لا بين الحدود أو العواصم، وليست مسافات سفر. 10 تخمينات مختلفة و60 ثانية. لا تتكرر الدولة في الجولة.',shape:'اكتب اسم الدولة بالعربية أو الإنجليزية من شكل حدودها المبسّط. الشكل مكبّر ليناسب الإطار، وليس مقياساً للمساحة. 18 دولة في هذه النسخة، 3 محاولات و60 ثانية. الحدود مبسطة حسب Natural Earth وقد تختلف في المناطق المتنازع عليها.',flag:'اكتب اسم الدولة بالعربية أو الإنجليزية. نقبل الأسماء المعروفة المحددة واختلاف المسافات والتشكيل وبعض أشكال الحروف، وليس كل خطأ إملائي. لديك 3 محاولات و60 ثانية. أعلام رمزية بنسبة 4:3، لا نسب رسم رسمية.',area:'اختر الدولة الأكبر مساحة سطحية حسب بيانات 2024. تشمل المساحة المياه الداخلية وبعض الممرات الساحلية. لديك محاولة واحدة و60 ثانية. تغيير الاختيار قبل التثبيت لا يحسب محاولة.',population:'اختر الدولة الأكثر سكاناً حسب تقديرات منتصف 2024، لجميع السكان وليس المواطنين فقط. ليست أعداداً مباشرة الآن. لديك محاولة واحدة و60 ثانية. تغيير الاختيار قبل التثبيت لا يحسب محاولة.',chess:'الأبيض يلعب. اختر قطعة بيضاء ثم وجهة عليها نقطة، وثبّت النقلة التي تنهي هروب الملك الأسود. تغيير الاختيار لا يحسب محاولة. لديك 3 محاولات و60 ثانية. التدريب هنا نهايات ملك ووزير أو رخ ضد ملك، وليس مباراة كاملة.',arrows:'اختر ترتيب خروج السهام كلها. لا يخرج السهم إلا إذا خلا طريقه إلى الحافة من السهام التي لم تخرج قبله. الاختيار هنا مسودة؛ التراجع والمسح لا يحسبان محاولة. ثبّت بعد 16 سهماً. لديك 3 محاولات و60 ثانية.',reach:'اختر رقمين بالترتيب ثم عملية. يمكنك استعمال الناتج من جديد، ولا يلزم استعمال كل الأرقام. القسمة صحيحة فقط وبدون صفر، والقيم بين -1000000 و1000000. التراجع والمسح قبل التثبيت لا يحسبان محاولة. لديك 3 محاولات و60 ثانية.',number:'خمّن عدداً من 1 إلى 100. بعد كل خطأ تحصل على أعلى أو أقل. لديك 10 محاولات؛ اكتب العدد ثم ثبّت المحاولة.',arithmetic:'قد يظهر جمع أو طرح أو ضرب أو قسمة صحيحة. الناتج عدد صحيح غير سالب. احسب الناتج واكتبه ثم ثبّت المحاولة. لديك محاولة واحدة، فلا تثبّت قبل التأكد.',missing:'الأرقام من 1 إلى 25 موجودة ما عدا رقم واحد. اكتشف الغائب واكتبه ثم ثبّت المحاولة. لديك 3 محاولات.',order:'اضغط الأرقام الخمسة من الأصغر إلى الأكبر، ثم ثبّت الترتيب. التراجع خطوة أو المسح قبل التثبيت لا يحسب محاولة. لديك 3 محاولات.',path:'ابدأ من البداية، مرّ بكل مربع مرة واحدة بحركة أفقية أو عمودية، واجعل النجمة خطوتك 8 ثم أنهِ عند النهاية. ثبّت المسار بعد إكماله؛ التراجع خطوة أو المسح قبل التثبيت لا يحسب محاولة. لديك 3 محاولات.'}[kind]||''}

function undoDraft(kind){if(busy||!roundEditable()||!snapshot||snapshot.state.stage!=='tournament_round'||snapshot.state.kind!==kind||snapshot.own.done||readPending()||!$('answer').value)return;$('answer').value=$('answer').value.slice(0,-1);HubStorage.setItem(draftKey(),$('answer').value);drawOrder();drawPath();applyBusy()}
$('undoOrder').onclick=()=>undoDraft('order');$('undoPath').onclick=()=>undoDraft('path');

function drawTournamentTrack(room){const s=room.state,finished=s.stage==='tournament_finished',reveal=s.stage==='tournament_reveal',active=s.stage==='tournament_round',games=Array.isArray(s.playlist)?s.playlist:[];const visible=(active||reveal||finished)&&games.length>0;$('tournamentTrack').hidden=!visible;if(!visible){$('trackRounds').replaceChildren();$('trackSummary').textContent='';return}const completed=finished?games.length:reveal?s.number:Math.max(0,s.number-1),next=games[completed];$('trackSummary').textContent=finished?'اكتملت الجولات '+games.length+' من '+games.length+'. النتائج النهائية في الأعلى.':'الجولات المنتهية: '+completed+' من '+games.length+'. '+(active?'الجولة الحالية: '+names[s.kind]+'.':next?'التالية: '+names[next]+'. يفتحها المضيف.':'انتهت كل الجولات، يعرض المضيف النتيجة النهائية.');$('trackRounds').replaceChildren(...games.map((kind,i)=>{const li=document.createElement('li'),title=document.createElement('b'),status=document.createElement('span'),past=i<completed,current=active&&i===s.number-1;title.textContent=(i+1)+'. '+names[kind];status.textContent=past?'انتهت':current?'تلعب الآن':'لم تبدأ';status.className='small';if(current){li.setAttribute('aria-current','step');li.style.border='2px solid #b1ecd1';status.style.color='#b1ecd1'}li.append(title,status);return li}))}

function drawStandings(room){const final=room.state.stage==='tournament_finished';let rank=0,prior=null;const players=final?[...room.players].sort((a,b)=>b.score-a.score):room.players;$('players').replaceChildren(...players.map((p,i)=>{const li=document.createElement('li'),name=document.createElement('span'),score=document.createElement('b');if(final&&(i===0||p.score!==prior))rank=i+1;prior=p.score;name.textContent=(final?rank+'. ':'')+p.name+(p.id===room.me?' · أنت':'')+(p.id===room.host_id?' · المضيف':'');score.textContent=p.score===null?'النقاط مخفية':p.score+' نقطة';if(p.id===room.me){li.style.background='#243b46';li.style.borderRadius='10px';li.setAttribute('aria-label','نتيجتك: '+name.textContent+'، '+score.textContent)}li.append(name,score);return li}));$('finalSummary').hidden=!final;if(!final){$('finalSummary').replaceChildren();return}const history=room.history||[],solved=history.filter(r=>r.solved||(r.kind==='nearcity'&&r.nearcity_pin!==null)||(r.kind==='closest'&&r.closest_guess!==null)),points=history.reduce((sum,r)=>sum+r.points,0),mistakes=history.reduce((sum,r)=>sum+r.mistakes,0),own=players.find(p=>p.id===room.me),ownRank=own?players.filter(p=>p.score>own.score).length+1:null,tied=own?players.filter(p=>p.score===own.score).length>1:false;$('finalSummary').replaceChildren();for(const text of ['ملخّصك في البطولة','مركزك: '+ownRank+(tied?' (مشترك)':''),'مجموعك: '+points+' نقطة',(history.some(r=>['clock','acting','closest','nearcity'].includes(r.kind))?'جولات بنتيجة مثبتة أو حل صحيح: ':'حللت ')+solved.length+' من '+history.length+' جولات. مجموع الأخطاء: '+mistakes+'.']){const el=document.createElement(text==='ملخّصك في البطولة'?'h3':'p');el.textContent=text;$('finalSummary').append(el)}const note=document.createElement('p');note.className='mut small';note.textContent='المراكز المتساوية مشتركة. تفاصيل محاولاتك ونقاطك لكل جولة في سجلّك أدناه.';$('finalSummary').append(note)}

function drawNumberTrail(){const s=snapshot.state,show=s.kind==='number'&&['tournament_round','tournament_reveal'].includes(s.stage);$('numberTrail').hidden=!show;$('numberGuesses').replaceChildren();if(!show)return;let lo=1,hi=100;const labels={higher:'الرقم أعلى',lower:'الرقم أقل',correct:'صحيح',wrong:'غير صحيح'};for(const row of snapshot.own.number_guesses||[]){if(!Number.isInteger(row.guess)||row.guess<1||row.guess>100||!labels[row.hint])continue;const li=document.createElement('li'),value=document.createElement('bdi');value.dir='ltr';value.textContent=String(row.guess);li.append(value,' · '+labels[row.hint]);$('numberGuesses').append(li);if(row.hint==='higher')lo=Math.max(lo,row.guess+1);if(row.hint==='lower')hi=Math.min(hi,row.guess-1);if(row.hint==='correct')lo=hi=row.guess}const label=document.createElement('span'),range=document.createElement('bdi');label.textContent=lo===hi?'المجال حسب تلميحاتك: ':'المجال الممكن حسب تلميحاتك: ';range.dir='ltr';range.textContent=lo===hi?String(lo):lo+' – '+hi;$('numberRange').replaceChildren(label,range)}

function comparisonAllowed(){return !busy&&roundEditable()&&['area','population'].includes(snapshot.state.kind)&&!readPending()}
function updateComparisonControls(){for(const b of $('comparisonChoices').children)b.disabled=!comparisonAllowed()}
function drawComparison(){const s=snapshot.state,show=['area','population'].includes(s.kind)&&s.stage==='tournament_round'&&!snapshot.own.done;$('comparisonGame').hidden=!show;if(!show)return;$('comparisonChoices').replaceChildren(...s.comparison_choices.map(c=>{const b=document.createElement('button');b.type='button';b.dataset.slot=String(c.slot);b.textContent=c.name;b.className='secondary';b.style.cssText='min-height:72px;white-space:normal;overflow-wrap:anywhere';const chosen=$('answer').value===String(c.slot);b.setAttribute('aria-pressed',String(chosen));if(chosen){b.style.borderColor='#b1ecd1';b.style.background='#304d47'}b.onclick=()=>{if(!comparisonAllowed())return;$('answer').value=String(c.slot);HubStorage.setItem(draftKey(),$('answer').value);drawComparison();applyBusy();$('comparisonChoices').querySelector('[data-slot="'+c.slot+'"]').focus()};return b}));$('comparisonDraft').textContent=$('answer').value?'اخترت: '+s.comparison_choices.find(c=>String(c.slot)===$('answer').value)?.name+'، ثبّت المحاولة عندما تتأكد.':'اختر دولة ثم ثبّت المحاولة.';updateComparisonControls()}

function drawFlag(){const s=snapshot.state,show=s.kind==='flag'&&['tournament_round','tournament_reveal'].includes(s.stage);$('flagGame').hidden=!show;if(!show){$('flagPicture').removeAttribute('src');return}$('flagPicture').src='data:image/svg+xml;base64,'+s.flag_svg;$('flagPicture').alt=s.stage==='tournament_reveal'?'علم '+s.flag_name:'علم الدولة المطلوب تخمينها';}

function drawShape(){const s=snapshot.state,show=s.kind==='shape'&&['tournament_round','tournament_reveal'].includes(s.stage);$('shapeGame').hidden=!show;$('shapeOutline').setAttribute('d',show?s.shape_path:'');$('shapePicture').setAttribute('aria-label',s.stage==='tournament_reveal'?'شكل '+s.flag_name:'شكل الدولة المطلوب تخمينها')}

function updateGeoControls(){if(!snapshot)return;const enabled=!busy&&roundEditable()&&snapshot.state.kind==='hotcold'&&!readPending();$('geoCountry').disabled=!enabled}
function drawGeo(){const s=snapshot.state,show=s.kind==='hotcold'&&['tournament_round','tournament_reveal'].includes(s.stage);$('geoGame').hidden=!show;if(!show){$('geoTrail').replaceChildren();return}const trail=snapshot.own.geo_guesses||[],selection=$('answer').value;$('geoCountry').replaceChildren(Object.assign(document.createElement('option'),{value:'',textContent:'اختر دولة'}),...s.geo_choices.map(c=>Object.assign(document.createElement('option'),{value:c.iso,textContent:c.name,disabled:trail.some(t=>t.iso===c.iso)})));$('geoCountry').value=selection;$('geoCountry').onchange=()=>{if(busy||!roundEditable()||readPending())return;$('answer').value=$('geoCountry').value;HubStorage.setItem(draftKey(),$('answer').value)};const directions=['شمال ↑','شمال شرق ↗','شرق →','جنوب شرق ↘','جنوب ↓','جنوب غرب ↙','غرب ←','شمال غرب ↖'],trends={closer:'أقرب من السابق',farther:'أبعد من السابق',similar:'مسافة شبه متساوية'};$('geoTrail').replaceChildren(...trail.map((c,i)=>{const li=document.createElement('li');li.textContent=c.name+' · '+(c.correct?'هي الدولة الخفية!':c.km.toLocaleString('en-US')+' كم تقريباً · '+directions[c.direction]+(c.trend?' · '+trends[c.trend]:''));li.style.cssText='padding:10px 0;line-height:1.9';return li}));updateGeoControls()}
